        def __next__(self):
            while True:
                yield (self.args_list[self.idx], self.kwargs_list[self.idx])
                self.idx += 1
                self.idx = self.idx % self.n

    def reset(self):
        self.idx = 0

    @property
    def n_args(self):
        return self.n

