        self.column_widths = column_widths
        assert set(self.column_widths.keys()) == set(self.fieldnames)

    def print_table(self, rows: list[dataclasses.dataclass]):
        self._print_header()
        self._print_line()
        for row in rows:

        self._print_row(row)

def _print_header(self):
    for i, f in enumerate(self.fieldnames):
