async def generator(
    self
) -> AsyncGenerator[Union[RequestOutput, PoolingRequestOutput], None]:
    try:
        while True:
            result = await self._queue.get()
            if self._is_raisable(result):
                if result == STOP_ITERATION:
                    return
                raise result
            yield result
    except GeneratorExit:
        self._cancel(self.request_id)

